package io.github.astelev.around_planet.gametest;
import io.github.astelev.around_planet.space.*;
import io.github.astelev.around_planet.compat.*;
import net.minecraft.client.Minecraft;
import dev.ryanhcode.sable.sublevel.ServerSubLevel;
import dev.ryanhcode.sable.api.sublevel.SubLevelContainer;
final class MoonLandingClientSmoke {
 private static int ticks,stage;private static Throwable failure;private static java.util.UUID shipId,seatId;private static double expected;private static int landedAt;private static long moonSkyAt;
 static void tick(Minecraft mc,ServerSubLevel ship){ticks++;if(failure!=null)throw new AssertionError("Moon landing server",failure);if(ticks>900)throw new AssertionError("Moon landing timeout stage="+stage);
  if(stage==0){stage=1;mc.getSingleplayerServer().execute(()->{try{var level=ship.getLevel();var player=level.players().getFirst();shipId=ship.getUniqueId();seatId=player.getVehicle().getUUID();var c=SubLevelContainer.getContainer(level);c.physicsSystem().setPaused(true);io.github.astelev.around_planet.PlanetConfig.SPACE_GRAVITY.set(9.81);double r=new PlanetScale(io.github.astelev.around_planet.PlanetConfig.PLANET_SIZE.get()).radius();var sys=new CelestialSystem(r,9.81*r*r,0);var data=SpaceOrbitData.get(level.getServer());data.system(sys);var cell=SpaceCells.get(level).forShip(shipId);var state=new SpaceState(new SpaceVector(0,sys.moonRadius()+io.github.astelev.around_planet.PlanetConfig.MOON_LANDING.get()-1,0),new SpaceVector(30,-75,10));expected=state.velocity().length();data.put(cell.id(),new SpaceTrajectory(CelestialSystem.MOON,level.getGameTime(),state,sys.moonMu()));data.navigate(cell.id(),new SpaceNavigation(data.navigation(cell.id()).orElseThrow().planet(),SpaceFrame.IDENTITY));}catch(Throwable e){failure=e;}});return;}
  if(stage==1&&mc.level.dimension().equals(MoonSurface.dimension())&&mc.player.isPassenger()&&mc.player.getVehicle().getUUID().equals(seatId)){var moved=SubLevelContainer.getContainer(mc.level).getSubLevel(shipId);if(moved==null)return;stage=2;landedAt=ticks;moonSkyAt=io.github.astelev.around_planet.client.SpaceSkyRenderer.frames;mc.getSingleplayerServer().execute(()->{try{var level=mc.getSingleplayerServer().getLevel(MoonSurface.dimension());var c=SubLevelContainer.getContainer(level);c.physicsSystem().setPaused(true);var s=(ServerSubLevel)c.getSubLevel(shipId);if(s==null)throw new AssertionError("Missing lunar server ship");double speed=c.physicsSystem().getPipeline().getLinearVelocity(s,new org.joml.Vector3d()).length();if(Math.abs(speed-expected)>3)throw new AssertionError("Lunar velocity changed: "+speed);var player=level.players().getFirst();if(!player.getVehicle().getUUID().equals(seatId)||SpaceCells.contains(player))throw new AssertionError("Lunar seat/space membership invalid");io.github.astelev.around_planet.AroundPlanet.LOGGER.info("MOON_CLIENT_PASS native seat and real player crossed dimensions, lunar chunks and client sublevel visible, speed={}",speed);}catch(Throwable e){failure=e;}});return;}
  if(stage==2&&ticks-landedAt>50){if(io.github.astelev.around_planet.client.SpaceSkyRenderer.frames<=moonSkyAt)throw new AssertionError("Lunar stars/Earth sky did not render");net.minecraft.client.Screenshot.grab(mc.gameDirectory,"moon-landing-alpha43.png",mc.getMainRenderTarget(),m->{});stage=3;mc.getSingleplayerServer().execute(()->{try{var level=mc.getSingleplayerServer().getLevel(MoonSurface.dimension());var c=SubLevelContainer.getContainer(level);var s=(ServerSubLevel)c.getSubLevel(shipId);var center=s.logicalPose().transformPosition(new org.joml.Vector3d(s.getSelfMassTracker().getCenterOfMass()));double dy=io.github.astelev.around_planet.PlanetConfig.MOON_LANDING.get()+201-center.y;var seat=level.getEntity(seatId);var riders=ShipSeatTransfer.prepare(seat,0,dy,0);c.physicsSystem().getPipeline().teleport(s,new org.joml.Vector3d(s.logicalPose().position()).add(0,dy,0),s.logicalPose().orientation());s.updateBoundingBox();s.updateLastPose();riders.run();c.physicsSystem().getPipeline().resetVelocity(s);c.physicsSystem().getPipeline().addLinearAndAngularVelocity(s,new org.joml.Vector3d(30,75,10),new org.joml.Vector3d());var pilot=level.players().getFirst();if(!(Boolean)Class.forName("io.github.astelev.cruising.flight.FlightHooks").getMethod("isHighShipEntity",net.minecraft.world.entity.Entity.class).invoke(null,pilot))throw new AssertionError("Cruising did not activate on lunar ascent");io.github.astelev.around_planet.AroundPlanet.LOGGER.info("MOON_CRUISING_PASS height mode enabled on lunar surface");}catch(Throwable e){failure=e;}});return;}
  if(stage==3&&mc.level.dimension().equals(net.minecraft.world.level.Level.OVERWORLD)&&mc.player.isPassenger()&&SpaceCells.contains(mc.player)){stage=4;mc.getSingleplayerServer().execute(()->{try{var level=mc.getSingleplayerServer().overworld();var cell=SpaceCells.get(level).forShip(shipId);var data=SpaceOrbitData.get(level.getServer());if(cell==null||!data.get(cell.id()).orElseThrow().primary().equals(CelestialSystem.MOON))throw new AssertionError("Lunar ascent selected wrong primary");if(!level.players().getFirst().getVehicle().getUUID().equals(seatId))throw new AssertionError("Ascent lost seat");var player=level.players().getFirst();player.stopRiding();if(Math.abs(player.getY()-cell.y())>8||Math.abs(player.getX()-cell.x())>8||Math.abs(player.getZ()-cell.z())>8)throw new AssertionError("Ascent dismount leaked plot coordinates: "+player.position());io.github.astelev.around_planet.AroundPlanet.LOGGER.info("MOON_ROUNDTRIP_PASS seated pilot, native ship, full impulse, lunar primary and safe world-space dismount retained on ascent");}catch(Throwable e){failure=e;}});return;}
  if(stage==4&&ticks-landedAt>120){mc.stop();}
 }
}
